"""Local dataset utility only: original PDFs unchanged; no network/model calls."""
import pathlib,csv,json,hashlib,subprocess,re,collections
P=pathlib.Path(__file__).parent
N=['eupl-1.1','eupl-1.2']
pages={n:[re.sub(r'\s+',' ',t).strip() for t in (P/'extracted'/f'{n}.txt').read_text().split('\f') if t.strip()] for n in N}
def q(v,p,a,b=None):
 t=pages[N[v]][p-1]; i=t.index(a); j=t.index(b,i)+len(b) if b else i+len(a); return t[i:j]
rows=[]
def add(cat,question,answer,clause,old,new,notes=''):
 # old/new are physical-page, start, optional end
 ev=[]
 for v,s in enumerate([old,new]):
  p,*args=s; ev.append((p,q(v,p,*args)))
 rows.append(dict(id=f'CVD-{len(rows)+1:03}',question=question,expected_answer=answer,source_file='eupl-1.1.pdf | eupl-1.2.pdf',page_clause_cell=f'v1.1 physical PDF page {ev[0][0]}, {clause} | v1.2 physical PDF page {ev[1][0]}, {clause}',type=cat,evidence_quote=f'v1.1: {ev[0][1]} || v1.2: {ev[1][1]}',verification='Both quotes exact whitespace-normalized substrings on stated physical pages; semantic comparison curator-reviewed, not legal advice',old_file='eupl-1.1.pdf',old_page=ev[0][0],old_clause=clause,old_quote=ev[0][1],new_file='eupl-1.2.pdf',new_page=ev[1][0],new_clause=clause,new_quote=ev[1][1],coverage='Both complete English PDFs: v1.1 pp1–7; v1.2 pp1–6 (decision p1, licence annex pp2–6).',notes=notes))
C='changed-scope-or-wording'
add(C,'How does the opening licensing notice change from EUPL 1.1 to 1.2?','The displayed notice changes from “Licensed under the EUPL V.1.1” to “Licensed under the EUPL”; do not infer that existing 1.1-only grants automatically migrate.','opening notice',(1,'Licensed under the EUPL V.1.1'),(2,'Licensed under the EUPL'))
add(C,'Does the Original Work definition remain limited to software?','1.1 defines “The Original Work or the Software” as software; 1.2 defines “The Original Work” as work or software.','Article 1; Original Work',(1,'- The Original Work or the Software:','as the case may be.'),(2,'— ‘The Original Work’:','as the case may be.'))
add(C,'What object does the Licensee definition say the person uses?','The definition changes from usage of the Software to usage of the Work.','Article 1; Licensee',(2,'- The Licensee','terms of the Licence.'),(2,'— ‘The Licensee’','Licence.'))
add(C,'Does the modification grant say Original Work in both versions?','No. Article 2 changes “modify the Original Work” to “modify the Work”; both retain creating Derivative Works based upon the Work.','Article 2; modification grant',(2,'modify the Original Work,','based upon the Work,'),(2,'modify the Work,','based upon the Work,'))
add(C,'How does the limitations-on-copyright object change?','Article 4 replaces “Original Work or Software” with “Work”; it retains the protection for exceptions, exhaustion and other applicable limitations.','Article 4',(3,'Nothing in this Licence','thereto.'),(3,'Nothing in this Licence','thereto.'))
add(C,'What explicit version-only example is introduced in the copyleft clause?','1.2 adds the example “EUPL v. 1.2 only”; 1.1 already has a restriction for an Original Work expressly distributed only under that version. This is an added example, not a newly invented version-only right.','Article 5; Copyleft',(3,'Copyleft clause:','terms of the Licence.'),(3,'Copyleft clause:','terms of the Licence.'))
add(C,'What base work is referenced in the compatibility clause?','The compatibility clause changes the combination basis from the Original Work and another work to the Work and another work. The compatible-licence conflict priority remains.','Article 5; Compatibility',(3,'Compatibility clause:','shall prevail.'),(3,'Compatibility clause:','shall prevail.'))
add(C,'Does Article 9 retain the explicit charge-a-fee list?','1.1 expressly describes charging a fee for support, warranty, indemnity or other liability obligations/services. 1.2 instead says an additional agreement defining obligations or services consistent with the Licence. This textual removal does not prove fees are forbidden.','Article 9',(4,'While distributing','this Licence.'),(4,'While distributing','this Licence.'))
add(C,'What publication power is added to Article 13?','1.2 explicitly allows updated versions of the Appendix as well as linguistic or new licence versions; 1.1 mentions linguistic and/or new licence versions only.','Article 13; Commission publication power',(5,'The European Commission may publish','a unique version number.'),(5,'The European Commission may publish','a unique version number.'))
add(C,'Is the jurisdiction clause expressly qualified by a specific agreement in both versions?','No. 1.2 prefixes Article 14 with “Without prejudice to specific agreement between parties”; 1.1 directly states the litigation rules.','Article 14',(6,'Any litigation resulting','European Community.'),(5,'Without prejudice to specific agreement between parties,','European Union,'))
add(C,'Which EU licensors are named in the first jurisdiction limb?','1.1 names the European Commission; 1.2 names European Union institutions, bodies, offices or agencies. These are licence-role categories, not a change of named customer in a signed contract.','Article 14; EU licensor limb',(6,'Any litigation resulting','European Community.'),(5,'any litigation resulting','European Union,'))
add(C,'Which treaty article is referenced for the EU court?','The reference changes from article 238 of the Treaty establishing the European Community to article 272 of the Treaty on the Functioning of the European Union. This is a legal-reference change, not a payment amount.','Article 14; treaty reference',(6,'jurisdiction of the Court','European Community.'),(5,'jurisdiction of the Court','European Union,'))
add(C,'Can the applicable-law text be read without an agreement qualifier in 1.2?','No. Article 15 in 1.2 begins “Without prejudice to specific agreement between parties”; 1.1 states governing-law rules without that opening qualifier.','Article 15',(6,'This Licence shall be governed','registered office.'),(5,'15. Applicable Law Without prejudice to specific agreement between parties,','registered office,'))
add(C,'Does 1.2 retain the explicit Commission-litigation trigger for Belgian law?','1.1 explicitly applies Belgian law to litigation between the Commission as licensor and a licensee, and to non-EU licensors. 1.2 states Belgian law for licensors with no EU Member State seat, residence or registered office, subject to specific agreement; the Commission-litigation bullet is not retained.','Article 15; Belgian-law conditions',(6,'This licence shall be governed','European Union country.'),(5,'15. Applicable Law Without prejudice to specific agreement between parties,','a European Union Member State.'))
add(C,'Which GNU GPL versions are in the compatibility appendix?','1.1 lists GNU GPL v.2; 1.2 lists GPL v.2 and v.3. This is compatibility-list coverage, not a statement that GPL files themselves are included in this corpus.','Appendix; GPL',(7,'GNU General Public License (GNU GPL) v. 2'),(6,'GNU General Public License (GPL) v. 2, v. 3'))
add(C,'Which CeCILL versions are listed?','The entry expands from Cecill v.2.0 in 1.1 to CeCILL v.2.0 and v.2.1 in 1.2; capitalization also changes.','Appendix; CeCILL',(7,'Cecill v. 2.0'),(6,'CeCILL v. 2.0, v. 2.1'))
U='unchanged'
add(U,'Did the grant become royalty-bearing in 1.2?','No. Both Article 2 grants are royalty-free and non-exclusive.','Article 2; grant',(2,'The Licensor hereby grants','Original Work:'),(2,'The Licensor hereby grants','Original Work:'))
add(U,'Did the duration change to a fixed five-year term?','No. Both grants last for the duration of copyright vested in the Original Work.','Article 2; duration',(2,'for the duration of copyright vested in the Original Work:'),(2,'for the duration of copyright vested in the Original Work:'))
add(U,'Was use for all usages removed?','No. Both grant use of the Work in any circumstance and for all usage.','Article 2; use',(2,'use the Work in any circumstance and for all usage,'),(2,'use the Work in any circumstance and for all usage,'))
add(U,'Did the right to reproduce the Work disappear?','No. Both versions expressly grant reproduction of the Work.','Article 2; reproduction',(2,'reproduce the Work,'),(2,'reproduce the Work,'))
add(U,'Was the right to lend and rent removed?','No. Both versions grant lending and renting of the Work or copies.','Article 2; lending and renting',(2,'lend and rent the Work or copies thereof,'),(3,'lend and rent the Work or copies thereof,'))
add(U,'Did the source repository availability period change to 30 days?','No. Under Article 3 the repository is freely accessible for as long as the Licensor continues to distribute/communicate the Work in both versions.','Article 3',(2,'a repository where','Work.'),(3,'a repository where','communicate the Work.'))
add(U,'Were notices allowed to be removed in 1.2?','No. Both attribution clauses require intact copyright, patent or trademarks notices and licence/disclaimer notices.','Article 5; Attribution notices',(3,'the Licensee shall keep intact','disclaimer of warranties.'),(3,'The Licensee shall keep intact','disclaimer of warranties.'))
add(U,'Is the modification-date notice still required?','Yes. Both require prominent notices stating that the Work has been modified and the date of modification. This is a date-recording obligation, not a changed contract date.','Article 5; Attribution modification date',(3,'The Licensee must cause','date of modification.'),(3,'The Licensee must cause','date of modification.'))
add(U,'Can the Licensee impose additional restrictive terms after the revision?','No. Both copyleft clauses prohibit additional terms or conditions that alter or restrict the Licence.','Article 5; additional terms',(3,'The Licensee (becoming Licensor)','terms of the Licence.'),(3,'The Licensee (becoming Licensor)','terms of the Licence.'))
add(U,'Is permission to use licensor trademarks unrestricted in 1.2?','No. Both limit permission to reasonable customary origin description and reproduction of copyright notice.','Article 5; Legal Protection',(3,'Legal Protection:','copyright notice.'),(3,'Legal Protection:','copyright notice.'))
add(U,'Did the original licensor ownership/authority warranty disappear?','No. Article 6 preserves the warranty of ownership or licensing and power and authority to grant the Licence.','Article 6; original Licensor',(4,'The original Licensor warrants','grant the Licence.'),(4,'The original Licensor warrants','grant the Licence.'))
add(U,'Does the revision add an implied fitness warranty?','No. Both provide the Work as-is, without warranties including fitness for a particular purpose; both preserve the Article 6 copyright qualification.','Article 7',(4,'For the above reason,','Article 6 of this Licence.'),(4,'For the above reason,','Licence.'))
add(U,'Did 1.2 remove the liability exceptions for wilful misconduct or harm to natural persons?','No. Both Article 8 disclaimers begin with exceptions for wilful misconduct or damages directly caused to natural persons.','Article 8',(4,'Except in the cases of wilful misconduct','persons,'),(4,'Except in the cases of wilful misconduct','persons,'))
add(U,'Does accepting extra warranty/liability still require holding contributors harmless?','Yes. Both Article 9 texts require agreeing to indemnify, defend and hold each Contributor harmless for liability or claims arising from accepted warranty/additional liability.','Article 9; indemnity',(4,'only if You agree to indemnify,','additional liability.'),(4,'only if You agree to indemnify,','additional liability.'))
add(U,'Was automatic termination on breach replaced with a 90-day cure period?','No. Both Article 12 texts state automatic termination upon any breach; neither quoted termination rule supplies that cure period.','Article 12',(5,'The Licence and the rights granted','terms of the Licence.'),(5,'The Licence and the rights granted','of the Licence.'))
add(U,'Does the revised licence make English the sole controlling language?','No. Both Article 13 texts say all Commission-approved linguistic versions have identical value and parties may choose their linguistic version.','Article 13; languages',(5,'All linguistic versions','their choice.'),(5,'All linguistic versions','their choice.'))
absents=[
 ('What annual subscription price changed between these versions?','annual subscription price','annual subscription'),
 ('What invoice payment deadline changed from 30 to 60 days?','invoice payment deadline','invoice'),
 ('What named customer replaced Acme Ltd in the agreement?','named customer replacement','Acme'),
 ('What signed execution date changed for the supplier?','signed execution date for a supplier','signature'),
 ('What GST rate changed on the licence fee?','GST rate on a licence fee','GST'),
 ('What rupee liability cap changed between the versions?','rupee-denominated liability cap','rupee'),
 ('What service availability SLA percentage changed?','service availability SLA percentage','SLA'),
 ('What employment notice period changed in the contract?','employment notice period','employment notice')]
for question,subject,term in absents:
 for n in N: assert term.casefold() not in ' '.join(pages[n]).casefold()
 rows.append(dict(id=f'CVD-{len(rows)+1:03}',question=question,expected_answer=f'I could not find supporting evidence in the indexed text for {subject}. Coverage: both complete English EUPL PDFs (1.1 physical pp1–7; 1.2 physical pp1–6, including the decision and annex). These are public licence texts, not signed commercial agreements.',source_file='eupl-1.1.pdf | eupl-1.2.pdf',page_clause_cell='Searched scope: complete v1.1 physical pp1–7 and v1.2 physical pp1–6',type='not-in-corpus',evidence_quote='',verification=f'Full extracted-text scope reviewed; supplementary case-insensitive search for {term!r} yielded no match. Not a proof about any external document.',old_file='eupl-1.1.pdf',old_page='',old_clause='Full file searched; no supporting clause located',old_quote='',new_file='eupl-1.2.pdf',new_page='',new_clause='Full file searched; no supporting clause located',new_quote='',coverage='Both complete English PDFs: v1.1 pp1–7; v1.2 pp1–6 (decision p1, licence annex pp2–6).',notes='No fabricated supporting quote. Official publication dates are not contract execution dates; royalty-free is not an annual subscription price.'))
assert len(rows)==40
with (P/'gold.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
valid=[]
for n in N:
 f=P/'documents'/f'{n}.pdf'; info=subprocess.run(['pdfinfo',str(f)],capture_output=True,text=True,check=True)
 count=int(re.search(r'^Pages:\s+(\d+)',info.stdout,re.M)[1]);assert count==len(pages[n])
 # Render every page locally to a temporary file IN OWN output folder; discard only our temporary render.
 for pg in range(1,count+1):
  out=P/f'_render_{n}_{pg}'
  subprocess.run(['pdftoppm','-f',str(pg),'-l',str(pg),'-scale-to','160','-singlefile','-png',str(f),str(out)],check=True,capture_output=True)
  image=pathlib.Path(str(out)+'.png');assert image.read_bytes().startswith(b'\x89PNG');image.unlink()
 raw=f.read_bytes()
 valid.append(dict(filename=f.name,bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),type='PDF',parse_open=True,pages=count,validation='pdfinfo and pdftotext -layout exited 0; every physical page rendered with pdftoppm; all gold quotes checked on exact physical page after whitespace normalization',parser='Poppler pdfinfo / pdftotext / pdftoppm',warnings=info.stderr.strip(),source_url='https://interoperable-europe.ec.europa.eu/sites/default/files/custom-page/attachment/'+({'eupl-1.1':'eupl1.1.-licence-en_0.pdf','eupl-1.2':'eupl_v1.2_en.pdf'}[n])))
 # Page-addressable derived representation; original raw pdftotext also retained.
 rawpages=(P/'extracted'/f'{n}.txt').read_text().split('\f')
 (P/'extracted'/f'{n}.pages.json').write_text(json.dumps([dict(physical_page=i+1,text=t) for i,t in enumerate(rawpages) if t.strip()],ensure_ascii=False,indent=2))
(P/'validation.json').write_text(json.dumps(valid,indent=2))
(P/'audit.json').write_text(json.dumps(dict(gold_cases=len(rows),distribution=dict(collections.Counter(r['type'] for r in rows)),two_sided_quote_cases=32,quote_checks=64,quote_checks_passed=64,absence_scope_cases=8,source_documents=2,physical_pages=13,all_pages_rendered=True,semantic_review='Curator textual review; no independent legal reviewer or QA-model evaluation',no_model_execution=True),indent=2))
print(json.dumps(dict(cases=len(rows),distribution=dict(collections.Counter(r['type'] for r in rows)),sources=valid),indent=2))
